import{_ as e,c as t,o as d,b2 as r}from"./chunks/framework.CUhoHPxN.js";const h=JSON.parse('{"title":"操作日志设计文档","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-16-operlog-design.md","filePath":"superpowers/specs/2026-05-16-operlog-design.md"}'),c={name:"superpowers/specs/2026-05-16-operlog-design.md"};function a(i,o,n,s,l,g){return d(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="操作日志设计文档" tabindex="-1">操作日志设计文档 <a class="header-anchor vp-link" href="#操作日志设计文档" aria-label="Permalink to &quot;操作日志设计文档&quot;">​</a></h1><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><p>在 <code>quickboot</code> + <code>quick-ui</code> 中实现《操作日志需求文档》所述能力：审计后台用户操作，支持检索、排序、详情、单条/批量删除、清空、导出；采集侧采用 <strong>宽切面 + Spring 事件 + <code>IgnoreLogger</code></strong>（与 <code>原始需求/old/quick-boot</code> 同构）；表字段语义 <strong>对齐若依 <code>sys_oper_log</code></strong>，并扩展 <strong><code>trace_id</code></strong> 与统一响应/日志中的链路 id（<code>TraceIds</code> / MDC）一致，便于与文件日志关联追溯。</p><p>路径与权限以需求文档为真源：<code>/monitor/operlog/*</code>、<code>monitor:operlog:query|remove|export</code>。</p><h2 id="_2-已确认决策摘要" tabindex="-1">2. 已确认决策摘要 <a class="header-anchor vp-link" href="#_2-已确认决策摘要" aria-label="Permalink to &quot;2. 已确认决策摘要&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>决策</th></tr></thead><tbody><tr><td>API 前缀与权限</td><td><code>/monitor/operlog</code>，`monitor:operlog:query</td></tr><tr><td>HTTP 动词</td><td>与仓库约定一致：删除/清空用 <strong>POST</strong>；列表/详情 <strong>GET</strong>；导出 <strong>POST</strong>（与需求文档字面 <code>DELETE</code> 不一致，以本设计为准）</td></tr><tr><td>批量删除</td><td><strong>POST</strong> + body 传 <strong><code>ids</code></strong> 数组（支持单条）</td></tr><tr><td>采集策略</td><td><strong>宽切面</strong>（映射注解族切点）+ <strong>发布应用事件</strong> + <strong><code>@IgnoreLogger</code></strong>（<code>ALL</code> / <code>PARAMS</code> / <code>RESULT</code> 语义与旧栈一致）</td></tr><tr><td>表字段语义</td><td>对齐若依 <code>sys_oper_log</code>；主键与列名在 Flyway 中与 <strong>现有基线表主键策略</strong> 一致（实现阶段对照 <code>V1__baseline</code> 等迁移定稿）</td></tr><tr><td>操作状态</td><td><strong><code>status</code></strong>：<code>0</code> 正常、<code>1</code> 异常（与字典及需求一致），不使用旧 quick-boot 的 HTTP/业务码混用形态</td></tr><tr><td>模块/操作类型</td><td>切面无 RuoYi <code>@Log</code> 元数据时：<strong>优先</strong> 可选薄注解 <strong><code>@OperLogMeta</code></strong> 覆盖；否则用 <strong><code>@Tag</code> + <code>@Operation</code></strong> 拼出标题/展示用操作说明；再兜底「未分类」</td></tr><tr><td>脱敏</td><td>序列化为字符串后、<strong>入库前</strong> 调用项目统一脱敏能力（或小而专的 <code>OperLogSensitiveMasker</code>，规则与 <code>@Sensitive</code> 语义对齐）</td></tr><tr><td>导出</td><td>同步 Excel；筛选与列表一致；<strong>最大导出行数可配置</strong>（默认 <code>10000</code>）</td></tr><tr><td>写库失败</td><td><strong>不得阻断</strong>业务请求（与登录日志设计一致）</td></tr><tr><td>链路 id</td><td>表列 <strong><code>trace_id</code></strong>；事件 DTO 在切面 <strong><code>finally</code> 中写入 <code>TraceIds.current()</code></strong>；监听器落库以 DTO 为准；可空</td></tr><tr><td>管理端自记日志</td><td><code>/monitor/operlog/**</code> 建议使用 <strong><code>@IgnoreLogger(ALL)</code></strong>（或等价），避免列表/导出产生噪声或异常递归</td></tr></tbody></table></div><h2 id="_3-范围与非范围" tabindex="-1">3. 范围与非范围 <a class="header-anchor vp-link" href="#_3-范围与非范围" aria-label="Permalink to &quot;3. 范围与非范围&quot;">​</a></h2><h3 id="_3-1-范围" tabindex="-1">3.1 范围 <a class="header-anchor vp-link" href="#_3-1-范围" aria-label="Permalink to &quot;3.1 范围&quot;">​</a></h3><ul><li>Flyway：<code>sys_oper_log</code>（若依语义列 + <strong><code>trace_id</code></strong> + 必要索引）。</li><li>通用模块：<strong>日志切面</strong>、<strong>事件载荷</strong>、<strong>监听器落库</strong>、<code>IgnoreLogger</code>（或同名注解）、可选 <strong><code>@OperLogMeta</code></strong>。</li><li>监控模块：分页列表、详情、删除（含批量）、清空、导出。</li><li><code>quick-ui</code>：API、路由、列表页、详情、权限、菜单（与《登录日志》监控风格一致）。</li></ul><h3 id="_3-2-非范围-本期不做" tabindex="-1">3.2 非范围（本期不做） <a class="header-anchor vp-link" href="#_3-2-非范围-本期不做" aria-label="Permalink to &quot;3.2 非范围（本期不做）&quot;">​</a></h3><ul><li>异步导出、对象存储归档、采样率动态调参（可按二期扩展）。</li><li>替代 Micrometer/修改全局 tracing 传播机制（仅消费现有 <code>TraceIds</code>）。</li></ul><h2 id="_4-数据模型" tabindex="-1">4. 数据模型 <a class="header-anchor vp-link" href="#_4-数据模型" aria-label="Permalink to &quot;4. 数据模型&quot;">​</a></h2><h3 id="_4-1-sys-oper-log" tabindex="-1">4.1 <code>sys_oper_log</code> <a class="header-anchor vp-link" href="#_4-1-sys-oper-log" aria-label="Permalink to &quot;4.1 `sys_oper_log`&quot;">​</a></h3><p>对齐若依参考 DDL 语义，至少包含以下业务含义（物理列名以实现阶段 Flyway 为准，与若依保持一致便于对照）：</p><div class="vp-table"><table><thead><tr><th>含义</th><th>说明</th></tr></thead><tbody><tr><td>主键</td><td>与项目现有表主键生成策略一致</td></tr><tr><td><code>title</code></td><td>系统模块/标题</td></tr><tr><td><code>business_type</code></td><td>业务类型（字典）</td></tr><tr><td><code>method</code></td><td>方法名称（如 <code>ClassName.methodName</code> 短格式，与旧栈展示习惯可一致）</td></tr><tr><td><code>request_method</code></td><td>HTTP 方法</td></tr><tr><td><code>operator_type</code></td><td>操作类别（字典，若依语义）</td></tr><tr><td><code>oper_name</code></td><td>操作人员</td></tr><tr><td><code>dept_name</code></td><td>部门名称（可空）</td></tr><tr><td><code>oper_url</code></td><td>请求 URI</td></tr><tr><td><code>oper_ip</code></td><td>客户端 IP</td></tr><tr><td><code>oper_location</code></td><td>操作地点（IP 解析，可空）</td></tr><tr><td><code>oper_param</code></td><td>请求参数（JSON 字符串，截断上限在实现计划写死）</td></tr><tr><td><code>json_result</code></td><td>返回或错误摘要（截断上限在实现计划写死）</td></tr><tr><td><code>status</code></td><td><code>0</code> 正常 / <code>1</code> 异常</td></tr><tr><td><code>error_msg</code></td><td>异常信息（可空；与 <code>json_result</code> 分工：异常时优先填 <code>error_msg</code>，展示策略在 VO 层统一）</td></tr><tr><td><code>oper_time</code></td><td>操作时间；列表默认按此倒序；索引</td></tr><tr><td><code>cost_time</code></td><td>耗时（毫秒）</td></tr><tr><td><strong><code>trace_id</code></strong></td><td>链路 id；与 <code>TraceIds</code> / <code>R.traceId</code> 同源；<strong>可空</strong>；建议单列索引</td></tr></tbody></table></div><p><strong>字典</strong>：<code>business_type</code>、<code>operator_type</code>、<code>status</code> 等与 <code>sys_dict_data</code> 对齐的具体 <code>dict_type</code> 在实现阶段与现有字典种子统一命名。</p><h2 id="_5-采集与落库链路" tabindex="-1">5. 采集与落库链路 <a class="header-anchor vp-link" href="#_5-采集与落库链路" aria-label="Permalink to &quot;5. 采集与落库链路&quot;">​</a></h2><h3 id="_5-1-切面" tabindex="-1">5.1 切面 <a class="header-anchor vp-link" href="#_5-1-切面" aria-label="Permalink to &quot;5.1 切面&quot;">​</a></h3><ul><li><code>@Around</code> 切点覆盖 <strong>Controller 映射方法</strong>（与 <code>原始需求/old/quick-boot</code> 的 <code>LoggingAspect</code> 意图一致）；<code>@Order</code> 与现有切面链在实现阶段测定，避免与权限、事务冲突。</li><li><code>finally</code> 中：根据 <code>@IgnoreLogger</code> 决定是否发布事件、是否剔除参数/返回值；组装 <strong>事件 DTO</strong>（含起止时间、签名、参数、返回值、异常、<strong><code>traceId</code> = <code>TraceIds.current()</code></strong>）。</li><li>发布 <strong>同步应用事件</strong>（首期）；监听器内写库，<code>try/catch</code> 吞异常并打 error 日志。</li></ul><h3 id="_5-2-监听器" tabindex="-1">5.2 监听器 <a class="header-anchor vp-link" href="#_5-2-监听器" aria-label="Permalink to &quot;5.2 监听器&quot;">​</a></h3><ul><li>将 DTO 转为领域对象/实体：填若依列 + <strong><code>trace_id</code> 取自 DTO</strong>（不用监听器线程盲读 MDC，避免未来异步化丢链路）。</li><li>操作人、部门：从当前登录上下文解析；匿名可空。</li><li><strong>脱敏</strong>：对 <code>oper_param</code>、<code>json_result</code>（及必要时的 <code>error_msg</code>）在持久化前处理。</li></ul><h3 id="_5-3-排除路径" tabindex="-1">5.3 排除路径 <a class="header-anchor vp-link" href="#_5-3-排除路径" aria-label="Permalink to &quot;5.3 排除路径&quot;">​</a></h3><ul><li>通过配置维护忽略前缀（如 actuator、swagger、静态资源、<code>/error</code> 等），与 <code>@IgnoreLogger</code> 互补。</li></ul><h2 id="_6-后端-操作日志管理模块" tabindex="-1">6. 后端：操作日志管理模块 <a class="header-anchor vp-link" href="#_6-后端-操作日志管理模块" aria-label="Permalink to &quot;6. 后端：操作日志管理模块&quot;">​</a></h2><h3 id="_6-1-分层与包" tabindex="-1">6.1 分层与包 <a class="header-anchor vp-link" href="#_6-1-分层与包" aria-label="Permalink to &quot;6.1 分层与包&quot;">​</a></h3><ul><li>建议包路径：<code>io.github.genkidoudou.web.monitor.operlog</code>（与 <code>logininfor</code> 监控模块并列）。</li><li>Controller / Service / Mapper / Entity / QueryBo / Vo 分层与现有系统管理模块一致。</li></ul><h3 id="_6-2-接口-对外契约" tabindex="-1">6.2 接口（对外契约） <a class="header-anchor vp-link" href="#_6-2-接口-对外契约" aria-label="Permalink to &quot;6.2 接口（对外契约）&quot;">​</a></h3><div class="vp-table"><table><thead><tr><th>方法</th><th>路径</th><th>权限</th><th>说明</th></tr></thead><tbody><tr><td>GET</td><td><code>/monitor/operlog/list</code></td><td><code>monitor:operlog:query</code></td><td>分页 + 条件 + 白名单排序；默认 <code>oper_time</code> 降序</td></tr><tr><td>GET</td><td><code>/monitor/operlog/{operId}</code></td><td><code>monitor:operlog:query</code></td><td>详情（含 <code>trace_id</code>、请求/返回/异常等）</td></tr><tr><td>POST</td><td><code>/monitor/operlog/remove</code></td><td><code>monitor:operlog:remove</code></td><td>body：<code>ids</code>（<code>Long</code> 数组）</td></tr><tr><td>POST</td><td><code>/monitor/operlog/clean</code></td><td><code>monitor:operlog:remove</code></td><td>清空</td></tr><tr><td>POST</td><td><code>/monitor/operlog/export</code></td><td><code>monitor:operlog:export</code></td><td>body 与列表筛选同构；行数上限</td></tr></tbody></table></div><p><strong>查询条件</strong>：操作地址、系统模块、操作人员、业务类型、操作状态、操作时间区间；<strong>首期支持 <code>trace_id</code> 精确匹配</strong>（可选展示为截断 + 全量 tooltip 由前端定）。</p><p><strong>注解与校验</strong>：<code>@Tag</code>、<code>@Operation</code>、<code>@Parameter</code>、<code>@SaCheckPermission</code>；Jakarta Validation；业务失败使用项目自定义异常，禁止 <code>IllegalArgumentException</code> 作为业务信号。</p><h2 id="_7-前端-quick-ui" tabindex="-1">7. 前端（<code>quick-ui</code>） <a class="header-anchor vp-link" href="#_7-前端-quick-ui" aria-label="Permalink to &quot;7. 前端（`quick-ui`）&quot;">​</a></h2><ul><li>新增 <code>api/monitor/operlog</code> 对接上述接口。</li><li>列表：需求中的列 + <strong><code>trace_id</code></strong>；支持列排序（操作人员、操作日期、耗时）；多选删除、清空、导出。</li><li>详情：请求地址、请求方式、操作方法、请求参数、返回参数、异常信息、<strong>链路 id</strong>。</li><li>权限：<code>v-hasPermi</code> 等与三点权限一致。</li><li>菜单：Flyway 增加「操作日志」及按钮项、<code>menu_id</code> 与现有迁移错开；超级管理员授权。</li></ul><p>实现前须阅读 <code>DESIGN.md</code> 与 <code>sdd/前端代码规范.md</code>（见 <code>AGENTS.md</code>）。</p><h2 id="_8-测试与验收" tabindex="-1">8. 测试与验收 <a class="header-anchor vp-link" href="#_8-测试与验收" aria-label="Permalink to &quot;8. 测试与验收&quot;">​</a></h2><ul><li>列表筛选、排序、详情字段与列表可追溯（含 <strong><code>trace_id</code> 与同一请求下应用日志 <code>%X{traceId}</code> 一致</strong>）。</li><li>删除（单条/批量）、清空后列表为空并提示成功；导出非空且不超过行数上限。</li><li>写库异常不阻断任意被切面覆盖的业务接口。</li><li><code>/monitor/operlog</code> 自身接口不产生可观测的自循环日志风暴（<code>IgnoreLogger</code> 或路径排除生效）。</li></ul><h2 id="_9-后续步骤" tabindex="-1">9. 后续步骤 <a class="header-anchor vp-link" href="#_9-后续步骤" aria-label="Permalink to &quot;9. 后续步骤&quot;">​</a></h2><p>在单独会话中按 <strong>writing-plans</strong> 产出 <code>docs/superpowers/plans/2026-05-16-operlog.md</code> 的实现任务清单后再编码。</p><hr><p><strong>文档版本</strong>：2026-05-16<br><strong>关联需求</strong>：<code>原始需求/系统管理/操作日志-需求文档.md</code><br><strong>关联设计</strong>：<code>docs/superpowers/specs/2026-05-16-logininfor-design.md</code>（监控模块与 POST 删清约定）、<code>AGENTS.md</code><br><strong>参考实现</strong>：<code>原始需求/old/quick-boot</code>（<code>LoggingAspect</code>、<code>OperateLoggerEventListener</code>、<code>@IgnoreLogger</code>）</p>',39)])])}const u=e(c,[["render",a]]);export{h as __pageData,u as default};
